/**
 * Bar showing how much of a task is done (`design/components/progress.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/progress.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, derived, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/progress.module.css'

export type ProgressTone = NonNullable<ProgressProps['tone']>

export type ProgressShape = NonNullable<ProgressProps['shape']>

/** Bar showing how much of a task is done: the inputs it takes, by the React member's prop names. */
export interface ProgressProps {
  /**
   * Required, because an unnamed progress bar tells a screen reader nothing.
   */
  label: string
  /**
   * A bar as wide as its container, or a ring at an icon's size.
   */
  shape?: 'bar' | 'ring'
  /**
   * The ring's size, Spinner's sizes. A bar takes the width of its container and no size.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * `danger` is for a task that failed or ran past its budget, not for "nearly done".
   */
  tone?: 'accent' | 'danger'
  /**
   * 0–100, clamped, because a bar cannot show more than full or less than empty.
   */
  value: number
}

/** Bar showing how much of a task is done. */
@Component({
  selector: 'pm-progress',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<!-- ring -->
<div
[attr.class]="e2()"
data-shape="ring"
[attr.data-size]="e3()"
[attr.data-tone]="e4()"
role="progressbar"
[attr.aria-label]="e5()"
[attr.aria-valuenow]="e6()"
[attr.aria-valuemin]="e7()"
[attr.aria-valuemax]="e8()"
data-member="progress"
><!-- dial -->
<svg
[attr.class]="e9()"
aria-hidden="true"
focusable="false"
><!-- groove -->
<circle
[attr.class]="e10()"
cx="50%"
cy="50%"
r="50%"
></circle>
<!-- arc -->
<circle
[attr.class]="e11()"
[style.stroke-dashoffset]="e12()"
cx="50%"
cy="50%"
r="50%"
[attr.pathLength]="e8()"
></circle></svg></div>} @else {<!-- track -->
<div
[attr.class]="e13()"
[attr.data-tone]="e14()"
role="progressbar"
[attr.aria-label]="e15()"
[attr.aria-valuenow]="e16()"
[attr.aria-valuemin]="e17()"
[attr.aria-valuemax]="e18()"
data-member="progress"
><!-- fill -->
<div
[attr.class]="e19()"
[style.transform]="e20()"
></div></div>}`,
})
export class Progress {
  /**
   * Required, because an unnamed progress bar tells a screen reader nothing.
   */
  readonly label = input.required<ProgressProps['label']>()
  /**
   * A bar as wide as its container, or a ring at an icon's size.
   */
  readonly shape = input<Exclude<ProgressProps['shape'], undefined>, ProgressProps['shape']>(
    'bar',
    { transform: (value: ProgressProps['shape']) => (value === undefined ? 'bar' : value) },
  )
  /**
   * The ring's size, Spinner's sizes. A bar takes the width of its container and no size.
   */
  readonly size = input<Exclude<ProgressProps['size'], undefined>, ProgressProps['size']>('md', {
    transform: (value: ProgressProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * `danger` is for a task that failed or ran past its budget, not for "nearly done".
   */
  readonly tone = input<Exclude<ProgressProps['tone'], undefined>, ProgressProps['tone']>(
    'accent',
    { transform: (value: ProgressProps['tone']) => (value === undefined ? 'accent' : value) },
  )
  /**
   * 0–100, clamped, because a bar cannot show more than full or less than empty.
   */
  readonly value = input.required<ProgressProps['value']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      shape: () => this.shape(),
      size: () => this.size(),
      tone: () => this.tone(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly percent = derived(() => Math.min(100, Math.max(0, this.$p.value)))

  protected e1() {
    return this.$p.shape === 'ring'
  }

  protected e2() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return styles.ring
  }

  protected e3() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return this.$p.size
  }

  protected e4() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return this.$p.tone
  }

  protected e5() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return this.$p.label
  }

  protected e6() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return this.percent.value
  }

  protected e7() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return 0
  }

  protected e8() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return 100
  }

  protected e9() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return styles.dial
  }

  protected e10() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return styles.groove
  }

  protected e11() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return styles.arc
  }

  protected e12() {
    if (!(this.$p.shape === 'ring')) return undefined as never
    return `${100 - this.percent.value}`
  }

  protected e13() {
    if (this.$p.shape === 'ring') return undefined as never
    return styles.track
  }

  protected e14() {
    if (this.$p.shape === 'ring') return undefined as never
    return this.$p.tone
  }

  protected e15() {
    if (this.$p.shape === 'ring') return undefined as never
    return this.$p.label
  }

  protected e16() {
    if (this.$p.shape === 'ring') return undefined as never
    return this.percent.value
  }

  protected e17() {
    if (this.$p.shape === 'ring') return undefined as never
    return 0
  }

  protected e18() {
    if (this.$p.shape === 'ring') return undefined as never
    return 100
  }

  protected e19() {
    if (this.$p.shape === 'ring') return undefined as never
    return styles.fill
  }

  protected e20() {
    if (this.$p.shape === 'ring') return undefined as never
    return `scaleX(${this.percent.value / 100})`
  }
}
